update_rule.pseudocode:
if use_exogenous_marketing and data.marketing_spend[t] exists:
  spend_t = data.marketing_spend[t]
else:
  spend_t = marketing_spend_daily_base
base_reach = spend_t * marketing_effect_per_$
for each agent i:
  if adopted[i]: base_prob = base_reach * (1 - targeting_bias_toward_nonadopters)
  else: base_prob = base_reach * (1 + targeting_bias_toward_nonadopters)
  # cap probability and apply coverage
  p = min(1.0, base_prob)
  shown = Bernoulli(p * targeting_coverage)
  marketing_exposure_i = shown * (1 + message_effect_size * sensitivity_marketing_i)
output scalar.marketing_spend_today = spend_t
